import React, { useState } from 'react';
import { useAuth, DEMO_USERS } from '../context/AuthContext';

const ROLE_META = {
  student: { icon: '🎓', color: '#4f46e5', label: 'Student' },
  faculty: { icon: '👨‍🏫', color: '#0891b2', label: 'Faculty' },
  admin:   { icon: '🛡️',  color: '#b45309', label: 'Admin'   },
};

export default function Login() {
  const { login } = useAuth();
  const [email, setEmail]     = useState('');
  const [password, setPassword] = useState('');
  const [error, setError]     = useState('');
  const [loading, setLoading] = useState(false);

  const handleLogin = async () => {
    if (!email || !password) { setError('Please enter email and password.'); return; }
    setLoading(true);
    setError('');
    // Simulate a small delay for UX
    await new Promise(r => setTimeout(r, 400));
    const result = login(email, password);
    if (!result.success) setError(result.message);
    setLoading(false);
  };

  const quickLogin = (user) => {
    setEmail(user.email);
    setPassword(user.password);
    setError('');
  };

  return (
    <div className="login-page">
      <div className="login-left">
        <div className="login-brand">
          <div className="login-brand-icon">🎓</div>
          <div className="login-brand-name">Academic Portal</div>
          <div className="login-brand-tagline">Centralized Notice &amp; Calendar System</div>
        </div>
        <div className="login-features">
          <div className="login-feature"><span>📋</span> View all college notices</div>
          <div className="login-feature"><span>📅</span> Access academic calendar</div>
          <div className="login-feature"><span>🔔</span> Stay updated with events</div>
          <div className="login-feature"><span>✏️</span> Faculty &amp; Admin can post updates</div>
        </div>
      </div>

      <div className="login-right">
        <div className="login-card">
          <div className="login-card-title">Welcome Back</div>
          <div className="login-card-sub">Sign in to your account</div>

          <div className="login-form">
            <div className="form-row">
              <label className="form-label">Email</label>
              <input
                className="form-input"
                type="email"
                placeholder="your@college.edu"
                value={email}
                onChange={e => setEmail(e.target.value)}
                onKeyDown={e => e.key === 'Enter' && handleLogin()}
              />
            </div>
            <div className="form-row">
              <label className="form-label">Password</label>
              <input
                className="form-input"
                type="password"
                placeholder="Enter password"
                value={password}
                onChange={e => setPassword(e.target.value)}
                onKeyDown={e => e.key === 'Enter' && handleLogin()}
              />
            </div>
            {error && <div className="login-error">⚠️ {error}</div>}
            <button
              className="btn btn-primary"
              style={{ width: '100%', padding: '0.75rem', marginTop: '0.5rem', fontSize: '0.95rem' }}
              onClick={handleLogin}
              disabled={loading}
            >
              {loading ? 'Signing in…' : 'Sign In →'}
            </button>
          </div>

          {/* Quick login demo */}
          <div className="quick-login-section">
            <div className="quick-login-label">Quick Demo Login</div>
            <div className="quick-login-grid">
              {DEMO_USERS.filter((u, i) => [0, 2, 4].includes(i)).map(u => {
                const meta = ROLE_META[u.role];
                return (
                  <button key={u.id} className="quick-login-btn" onClick={() => quickLogin(u)}
                    style={{ '--role-color': meta.color }}>
                    <span className="quick-icon">{meta.icon}</span>
                    <span className="quick-role">{meta.label}</span>
                    <span className="quick-name">{u.name.split(' ')[0]}</span>
                  </button>
                );
              })}
            </div>
            <div className="quick-login-hint">Click a role to fill credentials, then Sign In</div>
          </div>
        </div>
      </div>
    </div>
  );
}
